function S=colony_app_parameters()
%COLONY_APP_PARAMETERS User-facing controls and their underlying option units.
data={ ...
 'PinkContrastThreshold','Pink color threshold','Detection',0.02,0.20,1,'Lower values detect fainter pink colonies.'; ...
 'PaleBrightnessThreshold','Pale colony threshold','Detection',0.08,0.45,1,'Lower values detect fainter pale colonies.'; ...
 'MinDiameterFraction','Minimum diameter (% of plate)','Detection',0.002,0.012,100,'Smaller values retain smaller objects, including more noise.'; ...
 'MaxDiameterFraction','Maximum diameter (% of plate)','Detection',0.025,0.09,100,'Larger values retain larger colonies or merged regions.'; ...
 'WatershedPeakFraction','Separation peak (% of plate)','Detection',0.00025,0.0016,100,'Lower values split touching colonies more readily.'; ...
 'SizeThresholdFraction','AD9 / AD24 size reference (%)','Classification',0.006,0.035,100,'Initial size reference relative to the plate diameter. The classifier also learns from color and shape.'; ...
 'CompositeReviewMargin','Review sensitivity','Classification',0.05,0.75,1,'Higher values flag more borderline results from the learned composite classifier.'; ...
 'SizeReviewFraction','Size review margin (%)','Classification',0.02,0.40,100,'For size-based labels, flag diameters this close to the AD9 / AD24 size reference.'; ...
 'BackgroundSigmaFraction','Background scale (% of plate)','Advanced',0.008,0.035,100,'Scale used to correct gradual lighting variation.'; ...
 'ArtifactFilterStrength','Ink / reflection rejection','Advanced',0,2,1,'Higher values reject more weak ink halos and reflections. Lower this if faint colonies are missed; zero disables the extra filter.'; ...
 'MinSolidity','Minimum solidity','Advanced',0.50,0.95,1,'Lower values retain more indented or irregular objects.'; ...
 'MinCircularity','Minimum circularity','Advanced',0.20,0.85,1,'Lower values retain less round objects.'; ...
 'MaxEccentricity','Maximum elongation','Advanced',0.80,0.995,1,'Higher values retain more elongated objects.'; ...
 'MaxImageDimension','Processing image size (pixels)','Advanced',900,2600,1,'Higher resolution retains detail but takes longer.'; ...
 'PlateInset','Automatic plate inset (%)','Advanced',0.85,1,100,'Used only when the plate boundary is detected automatically.'};
S=cell2struct(data,{'Name','Label','Tab','Minimum','Maximum','Factor','Tip'},2);
end
